body {
	margin: 0; padding: 0;
}

.wrapper {
    position: relative;
    width: 818px; height: 438px;
    margin: 0; padding: 0;
    font-family: sans-serif;
    border: 1px solid #000;
}

.wrapper2 {
    width: 450px; height: 390px;
    margin: 180px auto;
    font-family: sans-serif;
    font-size: 20px;
    color: #686868;
}

.left {
    float: left;
    margin: 10px 15px 0 0;
}

p {margin: 3px 0;}


.progress-bar {
    position: relative;
    width: 200px; 
	height: 15px;
    background: #f8f8f8;
    border: 1px solid #a6a6a6;
	margin: 0px auto;
}

.progress {
    height: 100%;
    background: #8feca1;
}

.percent {
    position: absolute;
    right: 5px; 
	top: 0px;
    font-size: 12px;
    color: #696969;
}


/* noconnection confirmation */

.noconnection-confirmation {
	position: absolute;
	top: 0px;
	left: 0px;
	width: 700px;
	background-color: white;
	border: none;
	padding: 9px;
	text-align: center;	
}

.noconnection-confirmation p {
	font-size: 22px;
	margin: 5px;
	padding: 0px;
}

.noconnection-confirmation .btn-ok, 
.noconnection-confirmation .btn-close {
    float: left;
    margin: 10px 10px 0 0;
    padding: 5px 30px;
    background: #93d150;
    cursor: pointer;    
}

.noconnection-confirmation .btn-ok:hover,
.noconnection-confirmation .btn-close:hover {
    background: #abe26f;
}

.noconnection-confirmation .btn-confirmation {
	float: left;
	text-align: center;
	margin: 0 0 10px 250px;
}
